INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261114-scotus-asylum-ban', 'supreme-court-agrees-to-hear-trump-asylum-ban-southern-border', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Supreme Court agrees to decide whether Trump can bar asylum claims at the southern border', 'The justices took up the administration''s appeal on Friday, Nov. 13, after lower courts found the order illegal. The ban stays in effect while the case is argued, with a decision expected by the end of June.', 'The Supreme Court on Friday, Nov. 13, agreed to hear the Trump administration''s appeal in the fight over President Donald Trump''s executive order barring asylum at the U.S.-Mexico border, the Associated Press reported. The administration is asking the justices to overturn lower-court rulings that found the order illegal. The policy has remained in effect during the litigation.

## How the case got here

Trump issued the proclamation on Jan. 20, 2025, his first day back in office. It suspended entry for certain migrants at the southern border and seeks to bar those covered from applying for asylum and other protections, according to reporting carried by Yahoo News. A federal judge ruled the restrictions unlawful, and a divided federal appeals court upheld key parts of that ruling.

## The arguments

The administration argues that the president can categorically deny asylum to migrants covered by the order and should not have to process applications it has already decided to reject. It also says long processing times contributed to a surge at the border, the AP reported.

Lawyers for the American Civil Liberties Union and the National Immigrant Justice Center say federal law lets people seek asylum no matter how they arrive, that claims must be weighed case by case, and that border crossings were already falling before Trump took office.

## What comes next

Arguments are expected in the coming months, with a decision likely by the end of June. PBS News reported it is the third major Trump immigration case before the court this term.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:10800:10835/full/pct:25/0/default.jpg', 'The U.S. Border Patrol station in Naco, Ariz., on the Mexico border (file). Photo: Carol M. Highsmith / Library of Congress (highsm.10835), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-14.sql', 8, 0, 'newsroom-assistant', '2026-11-14T10:45:00.000Z', '2026-11-14T10:45:00.000Z');
