INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261114-lutnick-nvidia-testimony', 'lutnick-agrees-to-testify-senate-banking-nvidia-megaspeed-bessent', 'newsroom', 'news_story', 'policy', 'EDITORIAL_REVIEW', 0, 'Lutnick agrees to testify on Nvidia chip sales as Bessent says Commerce held the pen on export limits', 'The Commerce secretary will appear before the Senate Banking Committee on Thursday, Dec. 10, a U.S. official said. Republicans want to know why a Singapore firm suspected of moving chips to China was not blacklisted sooner.', 'Commerce Secretary Howard Lutnick has agreed to testify before the Senate Banking Committee on Thursday, Dec. 10, a U.S. official told CBS News. The hearing follows growing scrutiny of how the Commerce Department oversaw exports of advanced AI chips after Nvidia CEO Jensen Huang resigned.

## The Megaspeed question

At the center of the questions is Singapore-based Megaspeed International. U.S. officials suspect the company of routing advanced Nvidia chips to China in violation of an export ban, CBS News reported. Commerce appears to have delayed adding Megaspeed to the Entity List, the federal list that would have restricted its access to those chips. CBS News reported that the company was previously led by Alice Huang, a suspected Chinese spy who had an affair with Jensen Huang.

## Pressure from Republicans

Sen. Jim Banks, R-Ind., a member of the Banking Committee, said on Fox News on Thursday, Nov. 12, that Lutnick''s department appeared to have used loopholes to allow some chip sales despite Trump''s directive against them, according to CBS News.

## Bessent points to Commerce

Treasury Secretary Scott Bessent told CNBC on Friday, Nov. 13, that Treasury, the War Department, the U.S. Trade Representative and the State Department had favored putting Megaspeed on the Entity List for months. He said Commerce "has the pen" and that questions about its internal process should go to Commerce. Bessent declined to comment on reported tension between him and Lutnick. The Commerce Department did not immediately respond to CBS News.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:10700:10750/full/pct:25/0/default.jpg', 'The Herbert C. Hoover Building, headquarters of the U.S. Department of Commerce, Washington (file). Photo: Carol M. Highsmith / Library of Congress (highsm.10750), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-14.sql', 8, 0, 'newsroom-assistant', '2026-11-14T10:45:00.000Z', '2026-11-14T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261114-lutnick-nvidia-testimony-src1', 'bd-20261114-lutnick-nvidia-testimony', 'Lutnick agrees to testify as Bessent blames him for not banning Nvidia chip exports to China-linked firm', 'https://www.cbsnews.com/news/howard-lutnick-scott-bessent-nvidia-megaspeed-testimony/', 'CBS News', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-14T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-14. Editor to confirm.', 'newsroom-assistant', '2026-11-14T10:45:00.000Z');
