INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261114-kansas-governor-holscher', 'cindy-holscher-wins-kansas-governor-race-masterson', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Democrat Cindy Holscher wins the Kansas governor''s race, holding the seat against Trump-backed Ty Masterson', 'The Associated Press called the race on Thursday, Nov. 12, after days of provisional-ballot counting. Holscher leads by about 7,600 votes out of nearly 1.1 million cast.', 'Democratic state Sen. Cindy Holscher has been elected governor of Kansas, defeating Republican Ty Masterson, the president of the state Senate, UPI reported. The Associated Press called the race on Thursday, Nov. 12, after days of provisional-ballot counting and local recounts following the Nov. 3 election.

## The margin

Holscher had 50.4% of the vote, or 551,243 votes, to Masterson''s 49.6%, or 543,599 votes, according to results compiled by MultiState. That is a lead of about 7,600 votes.

## Why it mattered

The race was seen as the most likely of this year''s 36 governor''s contests to flip from Democratic to Republican control, UPI reported. Masterson had President Donald Trump''s endorsement, and Kansas usually votes Republican for president and other offices. Holscher succeeds Democratic Gov. Laura Kelly, who is term-limited after eight years of working with a heavily Republican Legislature.

## The campaigns

Holscher campaigned against what she called "sweetheart deals" for billionaires and tied Masterson to the tax cuts passed under former Republican Gov. Sam Brownback, which she said caused budget crises before they were repealed. She also proposed a moratorium on new data centers and legal cannabis to raise state revenue. Masterson ran on lowering property taxes, according to UPI.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:67000:67089/full/pct:25/0/default.jpg', 'The Senate Chamber of the Kansas Capitol in Topeka (file). Photo: Carol M. Highsmith / Library of Congress (highsm.67089), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-14.sql', 7, 0, 'newsroom-assistant', '2026-11-14T10:45:00.000Z', '2026-11-14T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261114-kansas-governor-holscher-src1', 'bd-20261114-kansas-governor-holscher', 'Democrat Cindy Holscher elected governor of Kansas', 'https://www.yahoo.com/news/politics/articles/democrat-cindy-holscher-elected-governor-000736944.html', 'Yahoo News (UPI)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-14T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-14. Editor to confirm.', 'newsroom-assistant', '2026-11-14T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261114-kansas-governor-holscher-src2', 'bd-20261114-kansas-governor-holscher', 'Kansas Governor Election Results 2026: Cindy Holscher Wins', 'https://www.multistate.us/elections/governor-race/kansas-2026', 'MultiState', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-14T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-14. Editor to confirm.', 'newsroom-assistant', '2026-11-14T10:45:00.000Z');
INSERT OR IGNORE INTO story_events (id, story_id, from_status, to_status, actor, note, created_at) VALUES ('bd-20261114-kansas-governor-holscher-ev1', 'bd-20261114-kansas-governor-holscher', NULL, 'EDITORIAL_REVIEW', 'newsroom-assistant', 'Drafted from attributed reporting and primary sources; awaiting editor approval', '2026-11-14T10:45:00.000Z');
INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261114-ucla-illinois', 'ucla-22-illinois-14-bruins-10-0-dieffenbach-mizell', 'newsroom', 'news_story', 'college-football', 'EDITORIAL_REVIEW', 0, 'UCLA 22, Illinois 14: No. 4 Bruins stay perfect at 10-0 in the rain at the Rose Bowl', 'Ty Dieffenbach shook off an arm injury to throw two touchdown passes, and Scooter Jackson''s second interception sealed it on Friday, Nov. 13. UCLA visits Michigan on Saturday, Nov. 21.', 'No. 4 UCLA beat Illinois 22-14 on a rain-soaked Friday night, Nov. 13, at the Rose Bowl in Pasadena, Calif., improving to 10-0 overall and 7-0 in the Big Ten, CBS Sports reported. It is the third 10-0 start in program history, and the 10-game winning streak ties a school record, according to the Chicago Sun-Times. Illinois fell to 6-4 and 4-3, ending a four-game winning streak.

## Dieffenbach returns

Quarterback Ty Dieffenbach left in the second quarter with a left-arm injury and returned in the third, leading a scoring drive on his first series back. He finished 13 of 20 for 232 yards and two touchdowns and is 5-0 as the starter since Nico Iamaleava''s season-ending knee injury on Oct. 10, CBS Sports reported.

Aiden Mizell caught six passes for 176 yards, including a 54-yard touchdown on the fifth play of the game. Semaje Morgan added a 26-yard touchdown catch, and Mateen Bhaghani kicked field goals of 20 and 37 yards. UCLA led 10-0 at halftime.

## Defense wins in the rain

UCLA intercepted Illinois quarterback Katin Houser three times, recovered a fumble and recorded a safety. Scooter Jackson had two of the interceptions, the last with 2:50 left. Houser threw touchdown passes to Kaden Feagin and Collin Dixon but finished 16 of 34 for 176 yards, and Illinois managed 240 total yards. The Bruins lead the nation with 31 takeaways.

## Up next

UCLA plays at Michigan on Saturday, Nov. 21. Illinois hosts Iowa the same day.', 'Boston Daily Staff', 'https://tile.loc.gov/storage-services/service/pnp/habshaer/ca/ca2200/ca2274/photos/183172pv.jpg', 'A Rose Bowl football game in Pasadena, Calif., 1923 (historical file). Photo: Historic American Buildings Survey / Library of Congress (HABS CA-2667), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-14.sql', 7, 0, 'newsroom-assistant', '2026-11-14T10:45:00.000Z', '2026-11-14T10:45:00.000Z');
