INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261114-spurs-warriors', 'spurs-123-warriors-85-castle-32-eleventh-straight-win', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Spurs 123, Warriors 85: Stephon Castle scores 32 as San Antonio opens on an 18-0 run for an 11th straight win', 'The Spurs led by as many as 43 in the NBA Cup game on Friday, Nov. 13. Golden State played without Stephen Curry, who has an oblique tear and is expected to miss at least two weeks.', 'The San Antonio Spurs routed the Golden State Warriors 123-85 in an NBA Cup game in San Antonio on Friday, Nov. 13, extending the league''s longest active winning streak to 11 games, ESPN reported.

## A fast start

San Antonio opened with an 18-0 run, its largest to start a game in the past 30 seasons and the largest Golden State has allowed to open a game under coach Steve Kerr, according to ESPN. The Spurs led by 26 in the first quarter, by 30 at halftime and by as many as 43 late in the third quarter.

## Castle leads the way

Stephon Castle scored a season-high 32 points in 25 minutes, making 5 of 8 three-pointers, with five rebounds and six assists. He had 13 points in the first quarter. Victor Wembanyama added a reverse dunk off a lob from Castle during the opening run.

## Warriors short-handed

Stephen Curry sat out with an oblique tear and is expected to miss at least two weeks, ESPN reported. It was the Warriors'' most lopsided loss since a 40-point defeat to the Celtics on Jan. 20, 2025, and the second straight game in which Golden State never held a lead.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:27100:27125/full/pct:25/0/default.jpg', 'A bridge over the River Walk in downtown San Antonio (file). Photo: Carol M. Highsmith / Library of Congress (highsm.27125), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-14.sql', 6, 0, 'newsroom-assistant', '2026-11-14T10:45:00.000Z', '2026-11-14T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261114-spurs-warriors-src1', 'bd-20261114-spurs-warriors', 'Victor Wembanyama, Spurs open on 18-0 run, rout Warriors for 11th straight win', 'https://www.espn.com/nba/story/_/id/50478136/victor-wembanyama-spurs-rout-warriors-11th-straight-win', 'ESPN', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-14T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-14. Editor to confirm.', 'newsroom-assistant', '2026-11-14T10:45:00.000Z');
