INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261114-patriots-injury-report', 'patriots-injury-report-aj-brown-stevenson-questionable-lions-munich', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'A.J. Brown and Rhamondre Stevenson are among nine Patriots listed as questionable for Sunday''s game against the Lions in Munich', 'Carlton Davis III, Ben Brown and TreVeyon Henderson are ruled out for the 9:30 a.m. Eastern kickoff on Sunday, Nov. 15. The Patriots (5-4) have their bye the following week.', 'The Patriots ruled out three players and listed nine as questionable on their final injury report on Friday, Nov. 13, ahead of their game against the Detroit Lions in Munich, Patriots.com reported. Kickoff is at 9:30 a.m. Eastern on Sunday, Nov. 15, on FOX.

## Ruled out

Cornerback Carlton Davis III (knee) will miss his fifth game of the season. Center-guard Ben Brown (knee) and running back TreVeyon Henderson (illness) are also out.

## Questionable

Receiver A.J. Brown (ankle/knee) returned to limited practice and is expected to play, though the team could hold him out until after the bye, Patriots.com reported. Running back Rhamondre Stevenson (knee) was limited and could be used mainly in passing situations if he is not fully healthy. If Stevenson is out or limited, Corey Kiner would likely get most of the early-down carries.

Also questionable are safety Kevin Byard III (chest), tight end Cameron Latu (back), lineman Walter Rouse (concussion), safety Brenden Schooler (hamstring), cornerback Charles Woods (hamstring), fullback Reggie Gilliam (knee) and center-guard Greg Van Roten (hamstring). Gilliam and Van Roten could be activated from injured reserve on Saturday, Nov. 14.

## The matchup

New England is 5-4 and second in the AFC East, and Detroit is 6-2, according to the team''s game preview. It is the Patriots'' sixth international game and second in Germany. Drake Maye has thrown at least two touchdown passes in six straight games. The Patriots have their bye in Week 11.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:cph:3c20000:3c25000:3c25300:3c25359/full/pct:50/0/default.jpg', 'A Yale-Harvard football game, early 20th century (historical file). Photo: Library of Congress Prints and Photographs Division (cph.3c25359), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-14.sql', 6, 0, 'newsroom-assistant', '2026-11-14T10:45:00.000Z', '2026-11-14T10:45:00.000Z');
